declare(strict_types=1);$c=json_decode(file_get_contents($argv[1]),true,32,JSON_THROW_ON_ERROR);file_put_contents('/proc/self/comm','lsphp');cli_set_process_title('lsphp');$pipes=[];$p=proc_open([PHP_BINARY,$argv[2],$argv[1],str_repeat('x',256)],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($p))exit(2);fclose($pipes[0]);stream_set_timeout($pipes[1],5);$ready=fgets($pipes[1]);if(trim((string)$ready)!=='READY')exit(3);echo 'READY'.PHP_EOL;flush();$deadline=hrtime(true)+30000000000;try{while(!is_file($c['stop'])&&hrtime(true)<$deadline)usleep(10000);}finally{file_put_contents($c['stop'],'stop');$until=hrtime(true)+2000000000;do{$s=proc_get_status($p);if(!$s['running'])break;usleep(10000);}while(hrtime(true)<$until);if($s['running'])proc_terminate($p,9);fclose($pipes[1]);fclose($pipes[2]);proc_close($p);}
